const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const grafton = ee.Geometry.Point([152.9339, -29.6819]);
  const startDate = '2020-01-14';
  const endDate = '2020-01-22';

  // 2. Data Acquisition - GPM IMERG precipitation data
  const precipCol = ee.ImageCollection('NASA/GPM_L3/IMERG_V06')
    .filterDate(startDate, endDate)
    .filterBounds(grafton);

  const collectionSize = precipCol.size().getInfo();
  console.log(`GPM Images in period: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("No precipitation data found for the period.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Sum precipitation over the period
  const totalPrecip = precipCol.sum();

  // 4. Calculate total rainfall in the region
  const stats = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: grafton,
    scale: 10000,
    maxPixels: 1e9
  });

  const precipMm = stats.get('precipitationCal').getInfo();
  console.log(`Total precipitation (mm): ${precipMm ? precipMm.toFixed(2) : 'No data'}`);

  // Check for valid data
  if (precipMm === null || precipMm === undefined || isNaN(precipMm)) {
    console.log("No valid precipitation data retrieved.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Convert mm to inches (1 inch = 25.4 mm)
  const precipInches = precipMm / 25.4;
  console.log(`Total precipitation (inches): ${precipInches.toFixed(2)}`);

  // 5. Validation & Final Answer
  if (precipInches > 6) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
